service-call.in-map:
{userGroupId:userGroupId, expectedRevision:expectedRevision, description:description,
                        groupTypeEnumId:(groupTypeEnumId || null), requireAuthcFactor:(requireAuthcFactor || 'N'),
                        ipAllowed:(ipAllowed || ''), reason:(reason || null)}

actions.script:
// a member's own page, by the mount's route for a user: a plain route by its href, a screen path by its url
// and parameters
const mountLib = ec.resource.script('component://tools/template/AdminMount.js')
const routes = mountLib.state().routes
const userLink = userId => {
    const link = mountLib.link(routes, 'user', userId) || {}
    return {userHref: link.plain ? link.href : '', userUrl: link.plain ? '' : link.url || '',
        userParameters: link.plain ? {} : link.parameters || {}}
}
members = scopedMembers.map(row => Object.assign({}, row, userLink(row.userId), {
    fromText: row.fromDate ? ec.l10n.format(Number(row.fromDate), 'yyyy-MM-dd HH:mm') : '',
    thruText: row.thruDate ? ec.l10n.format(Number(row.thruDate), 'yyyy-MM-dd HH:mm') : '',
    stateText: row.active ? (row.thruDate ? 'Member until ' + ec.l10n.format(Number(row.thruDate), 'yyyy-MM-dd') : 'Member')
        : row.ended ? 'Ended' : 'Starts ' + ec.l10n.format(Number(row.fromDate), 'yyyy-MM-dd')}))

set.from:
(found?.grants || []).filter(row => !row.ended).map(row => Object.assign({}, row, {
                        kindText: row.capabilityKindEnumId ? row.capabilityKindEnumId.replace('Cpk', '') : '',
                        thruText: row.thruDate ? ec.l10n.format(Number(row.thruDate), 'yyyy-MM-dd') : ''}))

(preview?.changeList || []).map(row => Object.assign({}, row, {
                        actionText: row.action === 'end' ? 'End' : 'Add', kindText: row.kind === 'artifact' ? 'App gate' : 'Permission',
                        resultText: !row.allowed ? row.reason : row.noChange ? 'No change' : row.before + ' → ' + row.after}))

render-mode.text:
${markerTexts.map(text => '<q-chip dense square class="q-ma-none q-mr-xs m-tonal ' +
                                    (text === 'Privileged' ? 'text-negative' : text.startsWith('Sealed') ? 'text-warning' : 'text-primary') + '">' +
                                    WebUtilities.encodeHtml(text) + '</q-chip>').join('')}
